const mix = (entries) => Object.entries(entries).map(([heritage, weight]) => ({ heritage: heritage, weight: weight }));
// The heritage mix of a country the roster carries at thin fidelity: what its
// region's public life looks like, with the countries whose population is not
// their neighbors' named below. A prior, like the rest of a thin record; the
// authored table in portraits.ts wins for any country it names.
