    "region-north-africa": mix({ mena: 0.9, "africa-west": 0.1 }),
    "region-west-africa": mix({ "africa-west": 1 }),
    "region-central-africa": mix({ "africa-central": 1 }),
    "region-east-africa": mix({ "africa-east": 1 }),
